"""Seating charts: students in last-name order by row."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _sort_key(student: Student) -> tuple:
    return (
        student.last_name.lower(),
        student.first_name.lower()
    )


def _label(student: Student) -> str:
    return f"{student.last_name}, {student.first_name}"


def _split(items: list, size: int) -> list:
    return [
        items[begin:begin + size]
        for begin in range(0, len(items), size)
    ]


def _row_line(number: int, group: List[Student]) -> str:
    names = " | ".join(_label(pupil) for pupil in group)
    return f"Row {number}: {names}"


# ---
def seating_rows(students: list, seats: int) -> List[str]:
    if seats <= 0 or not students:
        raise ProjectError("need students and seats")
    ordered = sorted(students, key=_sort_key)
    lines = enumerate(_split(ordered, seats), 1)
    return [_row_line(*pair) for pair in lines]

