import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError

WANTED = [
    "Row 1: Dunmere, Piet | Halloway, Juno",
    "Row 2: Zane, Omar"
]


def make_student(last: str, first: str) -> Student:
    return Student("id-" + last, last, first, "A")


def sample_class() -> list:
    return [
        make_student("Halloway", "Juno"),
        make_student("Zane", "Omar"),
        make_student("Dunmere", "Piet")
    ]


class SeatingTests(unittest.TestCase):
    def test_sorted_and_grouped_by_row(self):
        result = seating_rows(sample_class(), 2)
        self.assertEqual(result, WANTED)

    def test_zero_seats_raises(self):
        with self.assertRaises(ProjectError):
            seating_rows(sample_class(), 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ProjectError):
            seating_rows(sample_class(), -1)

    def test_no_students_raises(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)
